  // Move player forward (upwards)
  player.y -= PLAYER_SPEED * dt;
  // Keep player within canvas bounds for visibility
  player.visible = player.x >= 0 && player.x <= canvas.width && player.y >= 0 && player.y <= canvas.height;

  // Update squeeze timer
  if (squeezeTimer > 0) {
    squeezeTimer -= dt;
    if (squeezeTimer < 0) squeezeTimer = 0;
  }

  // Handle squeeze input (Space key)
